using System.Collections;
using WypozyczalniaSportowa.Domain.Exceptions;
namespace WypozyczalniaSportowa.Domain;

public sealed class Inventory<T> : IEnumerable<T> where T : Equipment { private readonly List<T> _items = []; private readonly Dictionary<int, T> _byId = []; private readonly HashSet<string> _names = new(StringComparer.OrdinalIgnoreCase); public int Count => _items.Count; public T this[int id] => Find(id); public T this[string name] => Find(name); public void Add(T item) { if (_byId.ContainsKey(item.Id)) throw new DomainValidationException($"Id {item.Id} istnieje."); if (!_names.Add(item.Name)) throw new DomainValidationException($"Nazwa '{item.Name}' jest zajęta."); _items.Add(item); _byId.Add(item.Id, item); } public bool Remove(int id) { if (!_byId.Remove(id, out var item)) return false; _items.Remove(item); _names.Remove(item.Name); return true; } public T Find(int id) => _byId.TryGetValue(id, out var item) ? item : throw new KeyNotFoundException($"Brak sprzętu #{id}."); public T Find(string name) => _items.FirstOrDefault(x => x.Name.Equals(name, StringComparison.OrdinalIgnoreCase)) ?? throw new KeyNotFoundException($"Brak sprzętu '{name}'."); public IEnumerable<T> Available() => _items.Where(x => x.IsAvailable).OrderBy(x => x); public IEnumerator<T> GetEnumerator() { foreach (var item in _items) yield return item; } IEnumerator IEnumerable.GetEnumerator() => GetEnumerator(); public override string ToString() => $"Magazyn: {Count} sprzętów"; }
